"""ConfigParser: a data structure combining O(1) hash map ops with O(1) min/max stack ops."""

from __future__ import annotations


class ConfigParser:
    """Supports put/get/remove (hash map) and push/pop/top/getMin/getMax (stack) all in O(1).

    Internally maintains:
      - A dict for key-value storage (put, get, remove).
      - A stack where each entry stores (value, running_min, running_max),
        enabling O(1) push, pop, top, getMin, getMax.
    """

    def __init__(self) -> None:
        self._store: dict[str, str] = {}
        self._stack: list[tuple[str, str, str]] = []  # (value, min, max)

    # --- Hash-map operations (O(1) average) ---

    def put(self, key: str, value: str) -> None:
        """Insert or update a key-value pair."""
        self._store[key] = value

    def get(self, key: str) -> str | None:
        """Return the value for *key*, or None if absent."""
        return self._store.get(key)

    def remove(self, key: str) -> bool:
        """Delete *key*. Returns True if it existed, False otherwise."""
        if key in self._store:
            del self._store[key]
            return True
        return False

    # --- Stack operations (all O(1)) ---

    def push(self, value: str) -> None:
        """Push *value* onto the stack, updating running min/max."""
        if self._stack:
            _, prev_min, prev_max = self._stack[-1]
            new_min = min(prev_min, value)
            new_max = max(prev_max, value)
        else:
            new_min = new_max = value
        self._stack.append((value, new_min, new_max))

    def pop(self) -> str | None:
        """Pop and return the top value, or None if the stack is empty."""
        if self._stack:
            value, _, _ = self._stack.pop()
            return value
        return None

    def top(self) -> str | None:
        """Return the top value without removing it, or None if empty."""
        if self._stack:
            value, _, _ = self._stack[-1]
            return value
        return None

    def getMin(self) -> str | None:
        """Return the minimum value currently on the stack, or None if empty."""
        if self._stack:
            _, running_min, _ = self._stack[-1]
            return running_min
        return None

    def getMax(self) -> str | None:
        """Return the maximum value currently on the stack, or None if empty."""
        if self._stack:
            _, _, running_max = self._stack[-1]
            return running_max
        return None

    def __len__(self) -> int:
        return len(self._stack)

    def __repr__(self) -> str:
        return f"ConfigParser(store={self._store}, stack_depth={len(self._stack)})"

